referenceSolutionTemplate:
#include <iostream>
#include <thread>
using namespace std;

int nums[20];
int n = 0;
int front = 0;
int back = 0;

void addFront() {
    int s = 0;
    for (int i = 0; i < n / 2; i++) s = s + nums[i];
    front = s;
}

void addBack() {
    int s = 0;
    for (int i = n / 2; i < n; i++) s = s + nums[i];
    back = s;
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) cin >> nums[i];

    thread t1(addFront);
    thread t2(addBack);
    t1.join();
    t2.join();

    cout << "前半 " << front << endl;
    cout << "后半 " << back << endl;
    cout << "一共 " << front + back << endl;
    return 0;
}
